python3 -c "
# mod 9 analysis: cubes mod 9 in {0,1,8}
# 2002 mod 9
print('2002 mod 9 =', 2002 % 9)
print('2002^2002 mod 9 =', pow(2002,2002,9))
# find min t such that 4 is achievable as sum of t elements of {0,1,8} mod 9
S={0}
for t in range(1,10):
    S={ (s+c)%9 for s in S for c in (0,1,8)}
    print('t=',t,'achievable set=',sorted(S),'contains 4?', 4 in S)
"

